BEGIN;

CREATE TABLE public.roles (
  role_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  role_name varchar(50) NOT NULL UNIQUE,
  description varchar(255)
);

CREATE TABLE public.unit_kerja (
  unit_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  kode_unit varchar(30) NOT NULL UNIQUE,
  nama_unit varchar(150) NOT NULL,
  parent_id integer,
  keterangan varchar(255),
  CONSTRAINT fk_unit_parent FOREIGN KEY (parent_id) REFERENCES public.unit_kerja (unit_id) ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE INDEX fk_unit_parent ON public.unit_kerja (parent_id);

CREATE TABLE public.jenis_surat (
  jenis_surat_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nama_jenis varchar(100) NOT NULL UNIQUE,
  keterangan varchar(255)
);

CREATE TABLE public.klasifikasi_arsip (
  klasifikasi_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  kode_klasifikasi varchar(50) NOT NULL UNIQUE,
  nama_klasifikasi varchar(150) NOT NULL,
  deskripsi text
);

CREATE TABLE public.ruangan (
  ruangan_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  unit_id integer NOT NULL,
  kode_ruangan varchar(50) NOT NULL,
  nama_ruangan varchar(100) NOT NULL,
  keterangan varchar(255),
  CONSTRAINT uq_ruangan_unit UNIQUE (unit_id, kode_ruangan),
  CONSTRAINT fk_ruangan_unit FOREIGN KEY (unit_id) REFERENCES public.unit_kerja (unit_id) ON UPDATE CASCADE
);

CREATE TABLE public.lemari (
  lemari_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ruangan_id integer NOT NULL,
  kode_lemari varchar(50) NOT NULL,
  nama_lemari varchar(100),
  keterangan varchar(255),
  CONSTRAINT uq_lemari_ruangan UNIQUE (ruangan_id, kode_lemari),
  CONSTRAINT fk_lemari_ruangan FOREIGN KEY (ruangan_id) REFERENCES public.ruangan (ruangan_id) ON UPDATE CASCADE
);

CREATE TABLE public.rak (
  rak_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  lemari_id integer NOT NULL,
  kode_rak varchar(50) NOT NULL,
  nama_rak varchar(100),
  keterangan varchar(255),
  CONSTRAINT uq_rak_lemari UNIQUE (lemari_id, kode_rak),
  CONSTRAINT fk_rak_lemari FOREIGN KEY (lemari_id) REFERENCES public.lemari (lemari_id) ON UPDATE CASCADE
);

CREATE TABLE public.users (
  user_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  username varchar(100) NOT NULL UNIQUE,
  password_hash varchar(255) NOT NULL,
  password_changed_at timestamp,
  nama_lengkap varchar(150) NOT NULL,
  email varchar(150) UNIQUE,
  role_id integer NOT NULL,
  unit_id integer,
  is_active boolean NOT NULL DEFAULT true,
  last_login timestamp,
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_user_role FOREIGN KEY (role_id) REFERENCES public.roles (role_id) ON UPDATE CASCADE,
  CONSTRAINT fk_user_unit FOREIGN KEY (unit_id) REFERENCES public.unit_kerja (unit_id) ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE INDEX fk_user_role ON public.users (role_id);
CREATE INDEX fk_user_unit ON public.users (unit_id);

CREATE TABLE public.arsip (
  arsip_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  unit_id integer NOT NULL,
  jenis_surat_id integer NOT NULL,
  klasifikasi_id integer,
  rak_id integer,
  no_registrasi varchar(100) NOT NULL UNIQUE,
  no_surat varchar(100) NOT NULL,
  perihal varchar(500) NOT NULL,
  tanggal_surat date NOT NULL,
  masa_simpan_tahun integer,
  tanggal_mulai_retensi date,
  tanggal_jatuh_tempo date,
  status_arsip text NOT NULL DEFAULT 'Inaktif' CHECK (status_arsip IN ('Inaktif', 'Permanen', 'Musnah')),
  penyimpanan_cloud varchar(500), detail_arsip text, keterangan text,
  created_by integer NOT NULL,
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  nomor_spk varchar(100), tanggal_spk date, vendor varchar(255), nama_pekerjaan varchar(500), nilai_spk numeric(18,2), kategori_nilai varchar(30), tanggal_mulai_pekerjaan date, tanggal_selesai_pekerjaan date, jangka_waktu integer, penanggung_jawab_unit_id integer, status_spk varchar(20),
  CONSTRAINT fk_arsip_created_by FOREIGN KEY (created_by) REFERENCES public.users (user_id) ON UPDATE CASCADE,
  CONSTRAINT fk_arsip_jenis FOREIGN KEY (jenis_surat_id) REFERENCES public.jenis_surat (jenis_surat_id) ON UPDATE CASCADE,
  CONSTRAINT fk_arsip_klasifikasi FOREIGN KEY (klasifikasi_id) REFERENCES public.klasifikasi_arsip (klasifikasi_id) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT fk_arsip_rak FOREIGN KEY (rak_id) REFERENCES public.rak (rak_id) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT fk_arsip_unit FOREIGN KEY (unit_id) REFERENCES public.unit_kerja (unit_id) ON UPDATE CASCADE
);
CREATE INDEX fk_arsip_jenis ON public.arsip (jenis_surat_id); CREATE INDEX fk_arsip_klasifikasi ON public.arsip (klasifikasi_id); CREATE INDEX fk_arsip_rak ON public.arsip (rak_id); CREATE INDEX fk_arsip_created_by ON public.arsip (created_by); CREATE INDEX idx_arsip_no_surat ON public.arsip (no_surat); CREATE INDEX idx_arsip_perihal ON public.arsip (perihal); CREATE INDEX idx_arsip_tanggal ON public.arsip (tanggal_surat); CREATE INDEX idx_arsip_status ON public.arsip (status_arsip); CREATE INDEX idx_arsip_unit ON public.arsip (unit_id); CREATE INDEX idx_arsip_jatuh_tempo ON public.arsip (tanggal_jatuh_tempo);

CREATE TABLE public.file_arsip (file_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, arsip_id bigint NOT NULL, nama_file varchar(255) NOT NULL, path_file varchar(500) NOT NULL, ekstensi varchar(20), mime_type varchar(100), ukuran_file bigint NOT NULL DEFAULT 0, checksum varchar(128), is_primary boolean NOT NULL DEFAULT false, uploaded_by integer NOT NULL, uploaded_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_file_arsip FOREIGN KEY (arsip_id) REFERENCES public.arsip (arsip_id) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT fk_file_user FOREIGN KEY (uploaded_by) REFERENCES public.users (user_id) ON UPDATE CASCADE);
CREATE INDEX fk_file_user ON public.file_arsip (uploaded_by); CREATE INDEX idx_file_arsip ON public.file_arsip (arsip_id);
CREATE TABLE public.jadwal_pemusnahan (jadwal_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, arsip_id bigint NOT NULL UNIQUE, tanggal_jatuh_tempo date NOT NULL, status_jadwal text NOT NULL DEFAULT 'Menunggu' CHECK (status_jadwal IN ('Menunggu', 'Mendekati', 'Siap Dimusnahkan', 'Sudah Dimusnahkan', 'Dibatalkan')), keterangan text, created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_jadwal_arsip FOREIGN KEY (arsip_id) REFERENCES public.arsip (arsip_id) ON UPDATE CASCADE);
CREATE INDEX idx_jadwal_tempo ON public.jadwal_pemusnahan (tanggal_jatuh_tempo); CREATE INDEX idx_jadwal_status ON public.jadwal_pemusnahan (status_jadwal);
CREATE TABLE public.notifikasi (notifikasi_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, arsip_id bigint NOT NULL, jenis_notifikasi text NOT NULL CHECK (jenis_notifikasi IN ('1 Tahun', '1 Bulan', 'H-7', 'Jatuh Tempo')), tanggal_notifikasi date NOT NULL, sudah_dikirim boolean NOT NULL DEFAULT false, tanggal_dikirim timestamp, read_at timestamp, created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT notifikasi_arsip_id_jenis_notifikasi_key UNIQUE (arsip_id, jenis_notifikasi), CONSTRAINT uq_notifikasi_arsip_jenis_tanggal UNIQUE (arsip_id, jenis_notifikasi, tanggal_notifikasi), CONSTRAINT fk_notifikasi_arsip FOREIGN KEY (arsip_id) REFERENCES public.arsip (arsip_id) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE public.pemusnahan (pemusnahan_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, jadwal_id bigint NOT NULL UNIQUE, tanggal_pemusnahan date NOT NULL, metode_pemusnahan varchar(100) NOT NULL, nomor_berita_acara varchar(100) UNIQUE, file_berita_acara varchar(500), keterangan text, dilakukan_oleh integer NOT NULL, created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_pemusnahan_jadwal FOREIGN KEY (jadwal_id) REFERENCES public.jadwal_pemusnahan (jadwal_id) ON UPDATE CASCADE, CONSTRAINT fk_pemusnahan_user FOREIGN KEY (dilakukan_oleh) REFERENCES public.users (user_id) ON UPDATE CASCADE);
CREATE INDEX fk_pemusnahan_user ON public.pemusnahan (dilakukan_oleh);
CREATE TABLE public.profile_photos (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id integer NOT NULL UNIQUE, file_name varchar(255) NOT NULL, file_path varchar(255) NOT NULL, created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_profile_photos_user FOREIGN KEY (user_id) REFERENCES public.users (user_id) ON DELETE CASCADE);
CREATE TABLE public.riwayat_arsip (riwayat_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, arsip_id bigint NOT NULL, user_id integer NOT NULL, aksi text NOT NULL CHECK (aksi IN ('CREATE', 'UPDATE', 'DELETE', 'UPLOAD', 'DOWNLOAD', 'PINDAH_LOKASI', 'UBAH_STATUS')), data_lama jsonb, data_baru jsonb, keterangan text, created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_riwayat_arsip FOREIGN KEY (arsip_id) REFERENCES public.arsip (arsip_id) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT fk_riwayat_user FOREIGN KEY (user_id) REFERENCES public.users (user_id) ON UPDATE CASCADE);
CREATE INDEX idx_riwayat_arsip ON public.riwayat_arsip (arsip_id); CREATE INDEX idx_riwayat_user ON public.riwayat_arsip (user_id); CREATE INDEX idx_riwayat_tanggal ON public.riwayat_arsip (created_at);

CREATE FUNCTION public.set_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at = CURRENT_TIMESTAMP; RETURN NEW; END; $$;
CREATE TRIGGER set_arsip_updated_at BEFORE UPDATE ON public.arsip FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TRIGGER set_jadwal_pemusnahan_updated_at BEFORE UPDATE ON public.jadwal_pemusnahan FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TRIGGER set_profile_photos_updated_at BEFORE UPDATE ON public.profile_photos FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TRIGGER set_users_updated_at BEFORE UPDATE ON public.users FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
