SELECT setval(pg_get_serial_sequence('public.roles', 'role_id'), COALESCE((SELECT MAX(role_id) FROM public.roles), 1), true);
SELECT setval(pg_get_serial_sequence('public.unit_kerja', 'unit_id'), COALESCE((SELECT MAX(unit_id) FROM public.unit_kerja), 1), true);
SELECT setval(pg_get_serial_sequence('public.jenis_surat', 'jenis_surat_id'), COALESCE((SELECT MAX(jenis_surat_id) FROM public.jenis_surat), 1), true);
SELECT setval(pg_get_serial_sequence('public.klasifikasi_arsip', 'klasifikasi_id'), COALESCE((SELECT MAX(klasifikasi_id) FROM public.klasifikasi_arsip), 1), true);
SELECT setval(pg_get_serial_sequence('public.ruangan', 'ruangan_id'), COALESCE((SELECT MAX(ruangan_id) FROM public.ruangan), 1), true);
SELECT setval(pg_get_serial_sequence('public.lemari', 'lemari_id'), COALESCE((SELECT MAX(lemari_id) FROM public.lemari), 1), true);
SELECT setval(pg_get_serial_sequence('public.rak', 'rak_id'), COALESCE((SELECT MAX(rak_id) FROM public.rak), 1), true);
SELECT setval(pg_get_serial_sequence('public.users', 'user_id'), COALESCE((SELECT MAX(user_id) FROM public.users), 1), true);
