CREATE VIEW public.view_arsip_lengkap AS SELECT a.arsip_id, a.no_registrasi, a.no_surat, a.perihal, a.tanggal_surat, a.status_arsip, a.masa_simpan_tahun, a.tanggal_mulai_retensi, a.tanggal_jatuh_tempo, a.penyimpanan_cloud, a.detail_arsip, u.kode_unit, u.nama_unit, js.nama_jenis, k.kode_klasifikasi, k.nama_klasifikasi, ru.kode_ruangan, ru.nama_ruangan, l.kode_lemari, l.nama_lemari, r.kode_rak, r.nama_rak, a.created_at, a.updated_at FROM public.arsip a JOIN public.unit_kerja u ON a.unit_id = u.unit_id JOIN public.jenis_surat js ON a.jenis_surat_id = js.jenis_surat_id LEFT JOIN public.klasifikasi_arsip k ON a.klasifikasi_id = k.klasifikasi_id LEFT JOIN public.rak r ON a.rak_id = r.rak_id LEFT JOIN public.lemari l ON r.lemari_id = l.lemari_id LEFT JOIN public.ruangan ru ON l.ruangan_id = ru.ruangan_id;
CREATE VIEW public.view_jadwal_pemusnahan AS SELECT jp.jadwal_id, a.arsip_id, a.no_registrasi, a.no_surat, a.perihal, u.nama_unit, a.status_arsip, jp.tanggal_jatuh_tempo, jp.status_jadwal, jp.tanggal_jatuh_tempo - CURRENT_DATE AS sisa_hari FROM public.jadwal_pemusnahan jp JOIN public.arsip a ON jp.arsip_id = a.arsip_id JOIN public.unit_kerja u ON a.unit_id = u.unit_id;
COMMIT;
